import { step, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "plum";

export function spawn() {
  return { vx: 0.6, vy: 0, energy: 100 };
}

export function update(slug) {
  if (slug.energy < 25) glide(slug, 0.5);
  step(slug);
  keepInside(slug);
}

export function draw(slug, pen) {
  pen.fill(BODY);
  pen.ellipse(0, 0, 16, 6);
}

