import { DAY_TICKS } from "../world/time.js";
import { step, wander } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

const BODY = "slateblue";
const LIGHT = "lime";

export function spawn() {
  return { vx: 0.5, vy: 0 };
}

export function update(squid) {
  wander(squid, 0.05);
  step(squid);
  bounce(squid);
}

export function draw(squid, pen, world) {
  pen.fill(BODY);
  pen.ellipse(0, 0, 10, 16);
  if ((world.tick % DAY_TICKS) / DAY_TICKS >= 0.5) {
    pen.fill(LIGHT);
    pen.circle(0, 6, 3);
  }
}

import { step } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

const BODY = "steelblue";

export function spawn() {
  return { vx: 3, vy: 0 };
}

export function update(sail) {
  sail.vx = sail.vx < 0 ? -3 : 3;
  sail.vy = 0;
  step(sail);
  bounce(sail);
}

export function draw(sail, pen) {
  if (sail.vx < 0) pen.flip();
  pen.fill(BODY);
  pen.ellipse(0, 0, 22, 6);
  pen.poly([-4, -6, 6, -16, 10, -6]);
}

