import { ENERGY_MAX } from "../world/energy.js";

const SHELL = "tan";
const BAR = "gold";

export function spawn() {
  return { vx: 0, vy: 0, energy: ENERGY_MAX };
}

export function update(clam) {
  clam.vx = 0;
}

export function draw(clam, pen) {
  pen.fill(SHELL);
  pen.ellipse(0, 0, 14, 8);
  if (clam.resting > 0) {
    pen.fill(BAR);
    pen.rect(-10, 12, (20 * clam.resting) / 300, 3);
  }
}

import { nearestFood } from "../world/food.js";
import { step, steer, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "sienna";

export function spawn() {
  return { vx: 0.8, vy: 0, energy: 0 };
}

export function update(grouper, world) {
  const full = grouper.energy >= 4 * 25;
  const food = full ? null : nearestFood(grouper, world);
  if (food) steer(grouper, food.x, food.y, 0.15);
  glide(grouper, 0.97);
  step(grouper);
  keepInside(grouper);
}

export function draw(grouper, pen) {
  pen.fill(BODY);
  pen.ellipse(0, 0, 24, 14);
}
